B.a_D=new A.mD("kim_seoa","\uae40\uc11c\uc544","\ub0b4 \uacf5\ucc45\uc774 \uacc4\uc18d \ud2c0\ub9b0 \uac78 \uc801\uace0 \uc788\uc5b4. \uae30\ub85d\ud558\ub294 \uc0ac\ub78c\uc774 \uae30\ub85d\uc744 \ubabb \ubbff\uc73c\uba74 \uc5ec\uae30 \uc788\uc744 \uc774\uc720\uac00 \uc5c6\uc796\uc544.","\ud2c0\ub9b0 \uac83\ub3c4 \uae30\ub85d\uc774\ub77c\ub294 \ub9d0\uc740\u2026 \uc0dd\uac01\ud574 \ubcfc\uac8c. \ub300\uc2e0 \ub0b4\uac00 \uadf8\ub9cc\ub450\uaca0\ub2e4\uace0 \ud55c \uac83\ub3c4 \uc801\uc5b4 \ub458 \uac70\uc57c.","\uae30\ub2e4\ub824 \uc900\ub2e4\uace0 \ud574 \uc918\uc11c \uace0\ub9c8\uc6cc. \uadf8\ub9cc\ub458 \uad8c\ub9ac\uac00 \uc788\ub2e4\ub294 \uac78 \uc78a\uace0 \uc788\uc5c8\uc5b4.","\ub124 \uc7a5\ubd80\ub97c \uac19\uc774 \ubcf4\uba74\u2026 \ub0b4 \uacf5\ucc45\uc774 \uc5b4\ub514\uc11c \uc5b4\uae0b\ub0ac\ub294\uc9c0\ub294 \uc54c \uc218 \uc788\uaca0\ub124. \uadf8\uac74 \ud574 \ubcfc\uac8c.")
B.a_G=new A.mD("lee_jian","\uc774\uc9c0\uc548","\uace0\uce60 \uc218 \uc5c6\ub294 \uac78 \uacc4\uc18d \ubcf4\uace0 \uc788\uc5b4. \ub098\ub294 \uace0\uccd0\uc9c0\ub294 \uac83\ub9cc \ub9cc\uc9c0\uace0 \uc2f6\uc5c8\ub294\ub370.","\ub354 \uc788\uc5b4 \ubcf4\ub77c\ub2c8\uae4c \uc788\uc5b4 \ubcfc\uac8c. \uadfc\ub370 \uc5b5\uc9c0\ub85c \ubd99\uc7a1\ub294 \uac74 \uc544\ub2c8\uc5c8\uc73c\uba74 \uc88b\uaca0\uc5b4.","\uc5b8\uc81c \uadf8\ub9cc\ub46c\ub3c4 \ub41c\ub2e4\uace0 \ud574\uc11c \uc624\ud788\ub824 \uc870\uae08 \ud3b8\ud574\uc84c\uc5b4. \uba70\uce60 \ub354 \ubcfc\uac8c.","\ub124 \uc6d0\uc7a5 \uc5f4\uc5b4 \ubcf4\uc790. \ud654\uba74 \ub9d0\uace0 \uc2e4\uc81c\ub85c \ubb50\uac00 \uc5b4\uae0b\ub0ac\ub294\uc9c0 \ubcf4\uba74 \uc190\uc774 \ub2e4\uc2dc \uc6c0\uc9c1\uc77c\uc9c0\ub3c4.")
B.a_F=new A.mD("choi_iseo","\ucd5c\uc774\uc11c","\uc22b\uc790 \ubcf4\ub294 \uac8c \uc810\uc810 \uc2eb\uc5b4\uc838. \uc5b5\uc9c0\ub85c \ud558\uba74 \uacb0\uc774 \ub354 \uc548 \ubcf4\uc5ec.","\uc870\uae08\ub9cc \ub354. \ub300\uc2e0 \uc2eb\uc5b4\uc9c0\uba74 \uadf8\ub54c\ub294 \uc9c4\uc9dc\ub85c \ub9d0\ud560\uac8c.","\uc2eb\ub2e4\uace0 \ub9d0\ud574\ub3c4 \ub418\ub294 \uac70\uc600\ub124. \uadf8\ub7fc \uc870\uae08 \uc26c\uc5c8\ub2e4 \ubcfc\uac8c.","\uac19\uc774 \ubcf4\uba74 \uc880 \ub0ab\uaca0\uc5b4. \ub124\uac00 \uae09\ud558\uac8c \ud310\ub2e8\ud55c \uc790\ub9ac\ub97c \ub0b4\uac00 \uc9da\uc5b4 \uc904\uac8c.")
