B.bJx=new A.nD(u.a6,u.R,"\uc624\ub298 \ubd84\uc704\uae30 \uc880 \ub2e4\ub974\uc9c0 \uc54a\uc544? \uc7a5 \uc5f4\ub9ac\uae30 \uc804\uc5d0 \ub2e4\ub4e4 \ud45c\uc815\ubd80\ud130 \ubcfc\uae4c?","\ubc29\uae08 \ub2e4\ub4e4 \uac19\uc740 \uc22b\uc790\uc5d0\uc11c \uba48\ucdc4\uc5b4. \uadf8\uac8c \uae30\ud68c\uc778\uc9c0 \uac81\uc778\uc9c0 \ud655\uc778\ud574 \ubcf4\uc790.","\ub05d\ub0ac\ub2e4! \uc774\uc81c \uc22b\uc790 \ub9d0\uace0 \uc624\ub298 \uc9c4\uc9dc \ub180\ub780 \uc21c\uac04 \ud558\ub098\uc529 \ub9d0\ud558\uae30.","\uc8fc\ub9d0\uc774\uba74 \uc0c8\ub85c\uc6b4 \ub370 \uac00 \ubcf4\uc790. \ub2f9\uc7a5 \ub098\uac00\uc790\ub294 \uac74 \uc544\ub2c8\uace0, \uac19\uc774 \uacc4\ud68d\ubd80\ud130!"," \ub124 \ubc18\uc751\uc740 \uc774\uc0c1\ud558\uac8c \uc81c\uc77c \uba3c\uc800 \ubcf4\uc774\ub354\ub77c."," \uc0ac\uc2e4 \ub124\uac00 \uc624\uba74 \ubd84\uc704\uae30\uac00 \uc5b4\ub5bb\uac8c \ubc14\ub014\uc9c0 \uae30\ub2e4\ub838\uc5b4."," \ub108\ud55c\ud14c\ub294 \uc7a5\ub09c \ub9d0\uace0 \uc9c4\uc9dc \uac71\uc815\ud55c \uac83\ub3c4 \ub9d0\ud560 \uc218 \uc788\uc5b4.")
B.bJy=new A.nD("assets/images/production_soft_painted/oh_jiwoo/02_cheerful_fang_wave_v1.png",u.et,"\uc624\ub298 \uccab \uac00\uc124. \ub2e4\ub4e4 \ud655\uc2e0\ud558\ub294 \uc885\ubaa9\uc77c\uc218\ub85d \ud55c \ubc88 \ub354 \uc758\uc2ec\ud574\uc57c \ud55c\ub2e4.","\uc18d\ubcf4\ucc98\ub7fc \ubcf4\uc774\ub294 \uc7a1\uc74c\uc774 \uc81c\uc77c \uc704\ud5d8\ud558\uc9c0. \ubc18\ub300 \uc124\uba85\ubd80\ud130 \ud558\ub098 \uc138\uc6cc \ubcfc\ub798?","\uc624\ub298 \ub0b4 \uc608\uce21\ub3c4 \ud558\ub098 \ud2c0\ub838\uc5b4. \ub124\uac00 \uc6c3\uae30 \uc804\uc5d0 \ubc18\ub840\ubd80\ud130 \uac19\uc774 \ucc3e\uc790.","\uc8fc\ub9d0 \ud1a0\ub860 \uc8fc\uc81c \uc811\uc218 \uc911. \uacb0\ub860 \uc5c6\ub294 \uc598\uae30\ub3c4 \uc7ac\ubbf8\uc788\uc73c\uba74 \ud569\uaca9."," \ub124 \ubc18\ub860\uc740 \uaf64 \uc4f8 \ub9cc\ud574\uc11c \ub530\ub85c \uc801\uc5b4 \ub480\uace0."," \ub108\ud55c\ud14c \ud2c0\ub9b0 \uac78 \ub4e4\ud0a4\ub294 \uac74 \uc804\ubcf4\ub2e4 \ub35c \uc2eb\uc5b4."," \ub124 \uc55e\uc5d0\uc11c\ub294 \ubaa8\ub978\ub2e4\uace0 \ub9d0\ud574\ub3c4 \ub2e4\uc74c \uc598\uae30\uac00 \uc774\uc5b4\uc9c0\ub2c8\uae4c \uc88b\uc544.")
B.bJC=new A.nD("assets/images/production_soft_painted/yoon_chaea/02_soft_smile_wave_v1.png",u.ga,"\uc624\ub298 \uc77c\uc815\uc740 \uc5b4\uc81c\uc640 \uac19\uc544 \ubcf4\uc5ec\ub3c4 \uc804\uc81c\uac00 \ud558\ub098 \ub2ec\ub77c. \uba3c\uc800 \ucc3e\uc73c\uba74 \ub9d0\ud574 \uc904\uac8c.","\uac00\uaca9 \ud558\ub098\ub9cc \ubcf4\uba74 \ub2a6\uc5b4. \uadf8 \uc22b\uc790\ub97c \ub9cc\ub4e0 \uad6c\uc870\uac00 \uc544\uc9c1 \uc720\uc9c0\ub418\ub294\uc9c0 \ubd10.","\uc624\ub298 \uacb0\uacfc\ub294 \uc815\ub9ac\ud588\uc5b4. \uacb0\ub860\ubcf4\ub2e4 \ub124\uac00 \uc911\uac04\uc5d0 \ubc84\ub9b0 \uac00\uc815\uc774 \uad81\uae08\ud574.","\uc0ac\ub78c \uc801\uc740 \uacf3\uc774\uba74 \ub098\uac00\ub3c4 \uad1c\ucc2e\uc544. \uacc4\ud68d\uc740 \ubbf8\ub9ac \uc138\uc6b0\ub294 \ud3b8\uc774 \uc88b\uace0."," \ub124 \uc0dd\uac01\uc740 \uacb0\ub860 \uc804\uc5d0 \ub4e4\uc5b4\ub3c4 \uad1c\ucc2e\uc744 \uac83 \uac19\uc544."," \uc544\uc9c1 \ub35c \uc815\ub9ac\ub410\uc9c0\ub9cc \ub108\ud55c\ud14c\ub294 \uc911\uac04\ubd80\ud130 \ub9d0\ud574 \ubcfc\uac8c."," \ub0b4 \uacc4\ud68d\uc5d0 \ub124\uac00 \uc788\ub294 \uac74 \uc774\uc81c \ubcc4\ub3c4 \uac00\uc815\uc774 \uc544\ub2c8\uc57c.")
